config:
kind: CustomResourceStateMetrics
spec:
  resources:
    - groupVersionKind: {group: myteam.io, version: v1, kind: Foo}
      metrics:
        - name: single
          each: {type: Gauge, gauge: {path: [spec, replicas]}}
        - name: obj
          each: {type: Gauge, gauge: {path: [status, active], labelFromKey: type}}
        - name: deep_obj
          each: {type: Gauge, gauge: {path: [status, sub], labelsFromPath: {active: [active]}, labelFromKey: type, valueFrom: [ready]}}
        - name: path_relative_valuefrom_value
          each: {type: Gauge, gauge: {path: [metadata], labelsFromPath: {name: [name]}, valueFrom: [creationTimestamp]}}
        - name: non_existent_path
          each: {type: Gauge, gauge: {path: [foo], labelsFromPath: {name: [name]}, valueFrom: [creationTimestamp]}}
        - name: non_numeric_value
          each: {type: Gauge, gauge: {path: [metadata, name]}}
        - name: nil_element_in_array
          each: {type: Gauge, gauge: {path: [status, sparse]}}
        - name: non_existent_path_with_nil_is_zero
          each: {type: Gauge, gauge: {path: [status, non-existent], valueFrom: [value], nilIsZero: true}}
        - name: nil_value_at_valuefrom_key_in_map
          each: {type: Gauge, gauge: {path: [status, nullable], labelFromKey: key, valueFrom: [value]}}
        - name: nil_value_at_valuefrom_key_in_map_with_nil_is_zero
          each: {type: Gauge, gauge: {path: [status, nullable], labelFromKey: key, valueFrom: [value], nilIsZero: true}}
        - name: exist_path_but_valuefrom_non_existent_single
          each: {type: Gauge, gauge: {path: [spec, replicas], valueFrom: [non-existent]}}
        - name: exist_path_but_valuefrom_non_existent_array
          each: {type: Gauge, gauge: {path: [status, condition_values], labelsFromPath: {name: [name]}, valueFrom: [non-existent]}}
        - name: array
          each: {type: Gauge, gauge: {path: [status, condition_values], labelsFromPath: {name: [name]}, valueFrom: [value]}}
        - name: timestamp
          each: {type: Gauge, gauge: {path: [metadata, creationTimestamp]}}
        - name: quantity_milli
          each: {type: Gauge, gauge: {path: [status, quantity_milli]}}
        - name: quantity_binarysi
          each: {type: Gauge, gauge: {path: [status, quantity_binarySI]}}
        - name: percentage
          each: {type: Gauge, gauge: {path: [status, percentage]}}
        - name: path_relative_valuefrom_percentage
          each: {type: Gauge, gauge: {path: [metadata], labelsFromPath: {name: [name]}, valueFrom: [percentage]}}
        - name: boolean_string
          each: {type: Gauge, gauge: {path: [spec, paused], nilIsZero: true}}
        - name: info
          each: {type: Info, info: {labelsFromPath: {version: [spec, version]}}}
        - name: info_nil_path
          each: {type: Info, info: {path: [does, not, exist]}}
        - name: info_label_from_key
          each: {type: Info, info: {path: [status, active], labelFromKey: type}}
        - name: info_label_from_path
          each: {type: Info, info: {path: [status, sub], labelsFromPath: {active: [active]}}}
        - name: stateset
          each: {type: StateSet, stateSet: {path: [status, phase], labelName: phase, list: [foo, bar]}}
        - name: stateset_nil_path
          each: {type: StateSet, stateSet: {path: [does, not, exist], labelName: phase, list: [foo, bar]}}
        - name: stateset_nil_valuefrom
          each: {type: StateSet, stateSet: {path: [status], valueFrom: [does, not, exist], labelName: phase, list: [foo, bar]}}
        - name: stateset_non_string_value
          each: {type: StateSet, stateSet: {path: [spec, replicas], labelName: phase, list: ["1", "2"]}}
        - name: stateset_non_string_valuefrom
          each: {type: StateSet, stateSet: {path: [status], valueFrom: [uptime], labelName: phase, list: [foo, bar]}}
        - name: status_conditions
          each: {type: Gauge, gauge: {path: [status, conditions, "[type=Ready]", status]}}
        - name: status_conditions_all
          each: {type: Gauge, gauge: {path: [status, conditions], labelsFromPath: {type: [type]}, valueFrom: [status]}}
        - name: eq_expression_matching
          each: {type: Info, info: {labelsFromPath: {bar: [metadata, annotations, "bar=baz"]}}}

spec:
  resources:
    - groupVersionKind: {group: myteam.io, version: v1, kind: Foo}
      commonLabels: {team: common}
      metrics:
        - name: star_info
          each: {type: Info, info: {labelsFromPath: {"*": [metadata, labels]}}}
        - name: prefix_info
          each: {type: Info, info: {labelsFromPath: {"p_*": [metadata, labels]}}}
        - name: two_stars_info
          each: {type: Info, info: {labelsFromPath: {"*": [metadata, labels], "*2": [metadata, annotations], "a_b": [metadata, labels, ok]}}}
        - name: family_level
          labelsFromPath: {"*": [metadata, labels], "p_*": [metadata, labels]}
          each: {type: Gauge, gauge: {path: [metadata, labels, ok]}}

spec:
  resources:
    - groupVersionKind: {group: myteam.io, version: v1, kind: Foo}
      metrics:
        - name: idx_info
          each: {type: Info, info: {labelsFromPath: {idx: [spec, order, "5"], ok: [metadata, name]}}}

spec:
  resources:
    - groupVersionKind: {group: g, version: v1, kind: Good}
      metrics: [{name: m, each: {type: Gauge, gauge: {path: [spec, replicas]}}}]
    - groupVersionKind: {group: g, version: v1, kind: Bad}
      metrics: [{name: m, each: {type: Gauge}}]

spec:
  resources:
    - groupVersionKind: {group: myteam.io, version: v1, kind: Foo}
      commonLabels: {hello: world}
      labelsFromPath: {foo: [metadata, annotations, bar]}
      metrics:
        - name: base
          each: {type: Gauge, gauge: {path: [spec, replicas]}}

spec:
  resources:
    - groupVersionKind: {group: myteam.io, version: v1, kind: Foo}
      commonLabels: {team: myteam}
      metrics: &m
        - name: foo
          each: {type: Gauge, gauge: {path: [status]}}
    - groupVersionKind: {group: myteam.io, version: v2, kind: Bar}
      commonLabels: {team: myteam}
      metrics: *m

spec:
  resources:
    - groupVersionKind: {group: apps, version: v1, kind: Deployment}
      labelsFromPath: {name: [metadata, name]}
      commonLabels: {hello: world}
      metrics:
        - name: test_metrics
          help: metrics for testing
          each: {type: Info, info: {path: [metadata, annotations], labelFromKey: test}}

spec:
  resources:
    - groupVersionKind: {group: apps, version: v1, kind: Deployment}
      labelsFromPath: {name: [metadata, name]}
      commonLabels: {hello: world}
      metricNamePrefix: apps_deployment
      metrics:
        - name: test_metrics
          help: metrics for testing
          each: {type: Info, info: {path: [metadata, annotations], labelFromKey: test}}

spec:
  resources:
    - groupVersionKind: {group: v.io, version: v1, kind: Values}
      labelsFromPath: {name: [metadata, name]}
      metrics:
        - {name: ints, each: {type: Gauge, gauge: {path: [spec, ints], labelFromKey: k}}}
        - {name: floats, each: {type: Gauge, gauge: {path: [spec, floats], labelFromKey: k}}}
        - {name: strings, each: {type: Gauge, gauge: {path: [spec, strings], labelFromKey: k}}}
        - {name: bools, each: {type: Gauge, gauge: {path: [spec, bools], labelFromKey: k}}}
        - {name: nulls, each: {type: Gauge, gauge: {path: [spec, nulls], labelFromKey: k}}}
        - {name: nulls_zero, each: {type: Gauge, gauge: {path: [spec, nulls], labelFromKey: k, nilIsZero: true}}}
        - {name: nested, each: {type: Gauge, gauge: {path: [spec, nested], labelFromKey: k}}}
        - {name: nested_arr, each: {type: Gauge, gauge: {path: [spec, nested, arr]}}}
        - {name: nested_obj_value, each: {type: Gauge, gauge: {path: [spec, nested, m]}}}
        - {name: list, each: {type: Gauge, gauge: {path: [status, list]}}}
        - {name: list_zero, each: {type: Gauge, gauge: {path: [status, list], nilIsZero: true}}}
        - {name: valuefrom_key, each: {type: Gauge, gauge: {path: [spec, ints], labelFromKey: k, valueFrom: [i1]}}}
        - {name: valuefrom_key_null, each: {type: Gauge, gauge: {path: [spec, nulls], labelFromKey: k, valueFrom: [a]}}}
        - {name: valuefrom_key_null_zero, each: {type: Gauge, gauge: {path: [spec, nulls], labelFromKey: k, valueFrom: [a], nilIsZero: true}}}
        - {name: valuefrom_key_bad, each: {type: Gauge, gauge: {path: [spec, strings], labelFromKey: k, valueFrom: [word]}}}
        - {name: valuefrom_key_zero, each: {type: Gauge, gauge: {path: [spec, strings], labelFromKey: k, valueFrom: [nokey], nilIsZero: true}}}
        - {name: valuefrom_two, each: {type: Gauge, gauge: {path: [spec, nested], labelFromKey: k, valueFrom: [m, x]}}}
        - {name: valuefrom_comma, each: {type: Gauge, gauge: {path: [spec, nested], labelFromKey: k, valueFrom: ["a,b"]}}}
        - {name: valuefrom_empty_part, each: {type: Gauge, gauge: {path: [spec, ints], labelFromKey: k, valueFrom: [""]}}}
        - {name: no_label_from_key, each: {type: Gauge, gauge: {path: [spec, ints]}}}
        - {name: conditions, each: {type: Gauge, gauge: {path: [status, conditions], labelsFromPath: {type: [type], reason: [reason], whole: []}, valueFrom: [status]}}}
        - {name: conditions_n, each: {type: Gauge, gauge: {path: [status, conditions], labelsFromPath: {type: [type]}, valueFrom: [n]}}}
        - {name: lookup_str, each: {type: Gauge, gauge: {path: [status, conditions, "[type=Synced]", n]}}}
        - {name: lookup_num, each: {type: Gauge, gauge: {path: [status, conditions, "[n=2]", n]}}}
        - {name: lookup_num_str, each: {type: Gauge, gauge: {path: [status, conditions, "[n=3.0]", n]}}}
        - {name: lookup_bool_word, each: {type: Info, info: {path: [status, conditions, "[status=true]"], labelsFromPath: {type: [type]}}}}
        - {name: lookup_bool_t, each: {type: Info, info: {path: [status, conditions, "[status=t]"], labelsFromPath: {type: [type]}}}}
        - {name: lookup_yes, each: {type: Info, info: {path: [status, conditions, "[status=yes]"], labelsFromPath: {type: [type]}}}}
        - {name: lookup_none, each: {type: Info, info: {path: [status, conditions, "[type=None]"], labelsFromPath: {type: [type]}}}}
        - {name: lookup_eq_in_value, each: {type: Info, info: {path: [status, conditions, "[type=a=b]"], labelsFromPath: {type: [type]}}}}
        - {name: lookup_on_map, each: {type: Info, info: {path: [spec, "[a=b]"], labelsFromPath: {x: []}}}}
        - {name: kv_match, each: {type: Info, info: {labelsFromPath: {phase: [status, "phase=Running"], nophase: [status, "phase=Other"], kv: [spec, m, "k=v"]}}}}
        - {name: neg_index, each: {type: Info, info: {labelsFromPath: {last: [status, list, "-1"], first: [status, list, "-4"], oob: [status, list, "-5"], plus: [status, list, "+1"], word: [status, list, x]}}}}
        - {name: index_on_scalar, each: {type: Info, info: {labelsFromPath: {x: [status, phase, "0"]}}}}
        - {name: stateset_list, each: {type: StateSet, stateSet: {path: [status, conditions], labelName: s, valueFrom: [status], list: ["True", "False", "Unknown"], labelsFromPath: {type: [type]}}}}
        - {name: stateset_label_override, each: {type: StateSet, stateSet: {path: [status], labelName: phase, valueFrom: [phase], list: [Running, Pending], labelsFromPath: {phase: [phase]}}}}
        - {name: stateset_empty_list, each: {type: StateSet, stateSet: {path: [status, phase], labelName: phase}}}
        - {name: info_list_scalars, each: {type: Info, info: {path: [status, list], labelsFromPath: {v: []}}}}
        - {name: info_map_scalars, each: {type: Info, info: {path: [spec, ints], labelFromKey: key, labelsFromPath: {v: []}}}}
        - {name: info_map_conflict, each: {type: Info, info: {path: [spec, ints], labelFromKey: i0, labelsFromPath: {i0: [i0]}}}}
        - {name: info_whole, each: {type: Info, info: {labelsFromPath: {nested: [spec, nested], arr: [spec, nested, arr], empty: [spec, nested, empty], ea: [spec, nested, emptyarr]}}}}
        - {name: info_map_empty_key, each: {type: Info, info: {path: [spec, m], labelFromKey: key}}}
        - {name: gauge_map_empty_key, each: {type: Gauge, gauge: {path: [spec, m], labelFromKey: key}}}
        - {name: timestamp_label, each: {type: Info, info: {labelsFromPath: {f: [spec, floats, f2], g: [spec, floats, f4], h: [spec, floats, f3], i: [spec, ints, big], j: [spec, ints, huge], k: [spec, floats, f8], l: [spec, floats, f9]}}}}

spec:
  resources:
    - groupVersionKind: {group: w.io, version: v1, kind: Weird}
      commonLabels: {"x-y": "common", "customresource_kind": "Overridden?"}
      labelsFromPath:
        name: [metadata, name]
        "weird-name": [metadata, name]
        "*": [metadata, labels]
      metrics:
        - name: weird_info
          help: "Help with \\ backslash\nand newline"
          each: {type: Info, info: {labelsFromPath: {"__a": [metadata, annotations], "ann_*": [metadata, annotations], "**": [metadata, annotations], "a.b": [metadata, name]}}}
        - name: gen_common
          commonLabels: {customresource_group: overridden, extra: "1"}
          each: {type: Gauge, gauge: {path: [spec, m], labelFromKey: key}}
        - name: label_from_key_vs_path
          each: {type: Gauge, gauge: {path: [spec, m], labelFromKey: name, labelsFromPath: {name: [metadata, name]}}}

---
---
spec: {resources: [{groupVersionKind: {group: a, version: v1, kind: K}, metrics: [{name: m, each: {type: Gauge, gauge: {}}}]}]}

%YAML 1.1
---
spec: {resources: [{groupVersionKind: {group: a, version: v1, kind: K}, metrics: [{name: m, each: {type: Gauge, gauge: {path: [spec, replicas]}}}]}]}

spec:
  resources:
    - groupVersionKind: {group: [a], version: v1, kind: K}

spec:
  resources:
    - groupVersionKind: &gvk {group: a, version: v1, kind: K}
      labelsFromPath: &lfp {name: [metadata, name]}
      metrics:
        - name: anchored
          labelsFromPath: *lfp
          each: {type: Gauge, gauge: {path: &p [spec, replicas]}}
        - name: anchored2
          each: {type: Gauge, gauge: {path: *p}}

spec:
  resources:
    - groupVersionKind: {group: a, version: v1, kind: K}
      commonLabels: {a: "1", a: "2"}

spec:
  resources:
    - {groupVersionKind: {group: a, version: v1, kind: Index}, metrics: [{name: m, each: {type: Gauge, gauge: {path: [spec, replicas]}}}]}
    - {groupVersionKind: {group: a, version: v1, kind: Index}, resourcePlural: indexes, metrics: [{name: m, each: {type: Gauge, gauge: {path: [spec, replicas]}}}]}
    - {groupVersionKind: {group: a, version: v1, kind: HTTPRoute}, metricNamePrefix: "", metrics: []}
    - {groupVersionKind: {group: a, version: v1, kind: ""}, metrics: []}
